This task involves implementing Pinia for centralized state management:

1. Set up Pinia in the Vue application:
   - Install required dependencies:
     ```bash
     npm install pinia
     # or
     yarn add pinia
     ```
   - Configure Pinia in the main.js/ts file:
     ```javascript
     import { createApp } from 'vue'
     import { createPinia } from 'pinia'
     import App from './App.vue'

     const app = createApp(App)
     app.use(createPinia())
     app.mount('#app')
     ```

2. Create an authentication store:
   ```javascript
   // stores/auth.js
   import { defineStore } from 'pinia'
   import axios from 'axios'

   export const useAuthStore = defineStore('auth', {
     state: () => ({
       user: null,
       token: localStorage.getItem('token') || null,
       isAuthenticated: false,
       loading: false,
       error: null
     }),
     getters: {
       getUser: (state) => state.user,
       isLoggedIn: (state) => !!state.token && state.isAuthenticated
     },
     actions: {
       async login(credentials) {
         this.loading = true
         this.error = null
         try {
           const response = await axios.post('/api/auth/login', credentials)
           this.token = response.data.token
           this.user = response.data.user
           this.isAuthenticated = true
           localStorage.setItem('token', this.token)
           return response
         } catch (error) {
           this.error = error.response?.data?.message || 'Authentication failed'
           throw error
         } finally {
           this.loading = false
         }
       },
       async logout() {
         try {
           await axios.post('/api/auth/logout')
         } catch (error) {
           console.error('Logout error:', error)
         } finally {
           this.token = null
           this.user = null
           this.isAuthenticated = false
           localStorage.removeItem('token')
         }
       },
       async fetchUserProfile() {
         this.loading = true
         try {
           const response = await axios.get('/api/auth/profile')
           this.user = response.data
           return response.data
         } catch (error) {
           this.error = error.response?.data?.message || 'Failed to fetch user profile'
           throw error
         } finally {
           this.loading = false
         }
       }
     }
   })
   ```

3. Create a meetings store:
   ```javascript
   // stores/meetings.js
   import { defineStore } from 'pinia'
   import axios from 'axios'

   export const useMeetingsStore = defineStore('meetings', {
     state: () => ({
       meetings: [],
       currentMeeting: null,
       loading: false,
       error: null,
       filters: {
         status: 'all',
         dateRange: null,
         search: ''
       },
       pagination: {
         page: 1,
         limit: 10,
         total: 0
       }
     }),
     getters: {
       getMeetings: (state) => state.meetings,
       getCurrentMeeting: (state) => state.currentMeeting,
       getFilters: (state) => state.filters,
       getPagination: (state) => state.pagination
     },
     actions: {
       async fetchMeetings() {
         this.loading = true
         try {
           const response = await axios.get('/api/meetings', {
             params: {
               ...this.filters,
               page: this.pagination.page,
               limit: this.pagination.limit
             }
           })
           this.meetings = response.data.items
           this.pagination.total = response.data.total
           return response.data
         } catch (error) {
           this.error = error.response?.data?.message || 'Failed to fetch meetings'
           throw error
         } finally {
           this.loading = false
         }
       },
       async fetchMeetingById(id) {
         this.loading = true
         try {
           const response = await axios.get(`/api/meetings/${id}`)
           this.currentMeeting = response.data
           return response.data
         } catch (error) {
           this.error = error.response?.data?.message || 'Failed to fetch meeting details'
           throw error
         } finally {
           this.loading = false
         }
       },
       async createMeeting(meetingData) {
         this.loading = true
         try {
           const response = await axios.post('/api/meetings', meetingData)
           await this.fetchMeetings()
           return response.data
         } catch (error) {
           this.error = error.response?.data?.message || 'Failed to create meeting'
           throw error
         } finally {
           this.loading = false
         }
       },
       async updateMeeting(id, meetingData) {
         this.loading = true
         try {
           const response = await axios.put(`/api/meetings/${id}`, meetingData)
           if (this.currentMeeting && this.currentMeeting.id === id) {
             this.currentMeeting = response.data
           }
           await this.fetchMeetings()
           return response.data
         } catch (error) {
           this.error = error.response?.data?.message || 'Failed to update meeting'
           throw error
         } finally {
           this.loading = false
         }
       },
       async deleteMeeting(id) {
         this.loading = true
         try {
           await axios.delete(`/api/meetings/${id}`)
           if (this.currentMeeting && this.currentMeeting.id === id) {
             this.currentMeeting = null
           }
           await this.fetchMeetings()
           return true
         } catch (error) {
           this.error = error.response?.data?.message || 'Failed to delete meeting'
           throw error
         } finally {
           this.loading = false
         }
       },
       updateFilters(filters) {
         this.filters = { ...this.filters, ...filters }
         this.pagination.page = 1 // Reset to first page when filters change
         return this.fetchMeetings()
       },
       updatePagination(pagination) {
         this.pagination = { ...this.pagination, ...pagination }
         return this.fetchMeetings()
       }
     }
   })
   ```

