5. Create a system state store:
   ```javascript
   // stores/system.js
   import { defineStore } from 'pinia'
   import axios from 'axios'

   export const useSystemStore = defineStore('system', {
     state: () => ({
       appConfig: null,
       notifications: [],
       darkMode: localStorage.getItem('darkMode') === 'true',
       sidebarCollapsed: localStorage.getItem('sidebarCollapsed') === 'true',
       loading: false,
       error: null
     }),
     getters: {
       getAppConfig: (state) => state.appConfig,
       getNotifications: (state) => state.notifications,
       isDarkMode: (state) => state.darkMode,
       isSidebarCollapsed: (state) => state.sidebarCollapsed
     },
     actions: {
       async fetchAppConfig() {
         this.loading = true
         try {
           const response = await axios.get('/api/system/config')
           this.appConfig = response.data
           return response.data
         } catch (error) {
           this.error = error.response?.data?.message || 'Failed to fetch app configuration'
           throw error
         } finally {
           this.loading = false
         }
       },
       async fetchNotifications() {
         this.loading = true
         try {
           const response = await axios.get('/api/notifications')
           this.notifications = response.data
           return response.data
         } catch (error) {
           this.error = error.response?.data?.message || 'Failed to fetch notifications'
           throw error
         } finally {
           this.loading = false
         }
       },
       toggleDarkMode() {
         this.darkMode = !this.darkMode
         localStorage.setItem('darkMode', this.darkMode)
       },
       toggleSidebar() {
         this.sidebarCollapsed = !this.sidebarCollapsed
         localStorage.setItem('sidebarCollapsed', this.sidebarCollapsed)
       },
       addNotification(notification) {
         this.notifications.unshift(notification)
         // Limit the number of notifications to prevent memory issues
         if (this.notifications.length > 100) {
