4. Create a loading store to manage loading states:
   ```typescript
   // src/stores/loading.ts
   import { defineStore } from 'pinia';

   interface LoadingState {
     isLoading: boolean;
     loadingRequests: Set<string>;
   }

   export const useLoadingStore = defineStore('loading', {
     state: (): LoadingState => ({
       isLoading: false,
       loadingRequests: new Set<string>(),
     }),

     actions: {
       startLoading(requestId: string) {
         this.loadingRequests.add(requestId);
         this.isLoading = true;
       },

       stopLoading(requestId?: string) {
         if (requestId) {
           this.loadingRequests.delete(requestId);
         }
         this.isLoading = this.loadingRequests.size > 0;
       },

       resetLoading() {
         this.loadingRequests.clear();
         this.isLoading = false;
       },
     },
   });
   ```

5. Create an error handling store or notification system:
   ```typescript
   // src/stores/notification.ts
   import { defineStore } from 'pinia';

   interface Notification {
     id: string;
     type: 'success' | 'error' | 'warning' | 'info';
     message: string;
     timeout?: number;
   }

   interface NotificationState {
     notifications: Notification[];
   }

   export const useNotificationStore = defineStore('notification', {
     state: (): NotificationState => ({
       notifications: [],
     }),

     actions: {
       addNotification(notification: Omit<Notification, 'id'>) {
         const id = Date.now().toString();
         this.notifications.push({
           id,
           ...notification,
         });

         if (notification.timeout !== 0) {
           setTimeout(() => {
             this.removeNotification(id);
           }, notification.timeout || 5000);
         }

         return id;
       },

       removeNotification(id: string) {
         const index = this.notifications.findIndex(n => n.id === id);
         if (index !== -1) {
           this.notifications.splice(index, 1);
         }
       },

       clearNotifications() {
         this.notifications = [];
       },
     },
   });
   ```

