     ```python
     class DocumentGenerationService:
         def __init__(self, model_name="KBLab/gpt-oss-20b-sv"):
             self.tokenizer = AutoTokenizer.from_pretrained(model_name)
             self.model = AutoModelForCausalLM.from_pretrained(
                 model_name,
                 device_map="auto",
                 load_in_8bit=True
             )

         def generate_document(self, template, variables, max_length=2048):
             """
             Generate document based on template and variables

             Args:
                 template (str): Document template with placeholders
                 variables (dict): Key-value pairs for template variables
                 max_length (int): Maximum token length for generation

             Returns:
                 str: Generated document text
             """
             # Fill in template variables
             prompt = template
             for key, value in variables.items():
                 prompt = prompt.replace(f"{{{key}}}", value)

             # Generate text
             inputs = self.tokenizer(prompt, return_tensors="pt").to(self.model.device)
             outputs = self.model.generate(
                 **inputs,
                 max_length=max_length,
                 temperature=0.7,
                 top_p=0.9
             )

             return self.tokenizer.decode(outputs[0], skip_special_tokens=True)
     ```

