           </div>

           <button @click="generateDocument" :disabled="isGenerating">
             {{ isGenerating ? 'Generating...' : 'Generate Document' }}
           </button>
         </div>

         <div class="document-preview" v-if="generatedDocument">
           <h3>Generated Document</h3>
           <div class="quality-score" v-if="qualityAssessment">
             Quality Score: {{ qualityAssessment.overall_score.toFixed(2) }}
