     <script>
     import { ref, reactive, onMounted } from 'vue';
     import { useApiService } from '@/services/api';

     export default {
       name: 'DocumentGenerator',
       setup() {
         const api = useApiService();
         const templates = ref([]);
         const selectedTemplate = ref('');
         const templateContent = ref('');
         const variables = reactive({});
         const generatedDocument = ref('');
         const isGenerating = ref(false);
         const qualityAssessment = ref(null);

         // Load available templates
         const loadTemplates = async () => {
           try {
             const response = await api.get('/templates/');
             templates.value = response.data.templates;
           } catch (error) {
             console.error('Failed to load templates:', error);
           }
         };

         // Load selected template
         const loadTemplate = async () => {
           if (!selectedTemplate.value) return;

           try {
             const response = await api.get(`/templates/${selectedTemplate.value}`);
             templateContent.value = response.data.content;

             // Extract variables from template
             const variableMatches = templateContent.value.match(/\{([^}]+)\}/g) || [];
             const uniqueVariables = [...new Set(variableMatches.map(v => v.slice(1, -1)))];

             // Reset variables object
             Object.keys(variables).forEach(key => delete variables[key]);

             // Initialize variables
             uniqueVariables.forEach(variable => {
               variables[variable] = '';
             });
           } catch (error) {
             console.error('Failed to load template:', error);
           }
         };

         // Generate document
         const generateDocument = async () => {
           isGenerating.value = true;

           try {
             const response = await api.post('/generate/', {
               template_name: selectedTemplate.value,
               variables: variables
             });

             generatedDocument.value = response.data.document;

             // Assess document quality
             const assessmentResponse = await api.post('/assess/', {
               document: generatedDocument.value,
               context: {
                 required_sections: ['introduction', 'body', 'conclusion'],
                 approved_terms: {}
               }
             });

             qualityAssessment.value = assessmentResponse.data;
           } catch (error) {
             console.error('Failed to generate document:', error);
           } finally {
             isGenerating.value = false;
           }
         };

         // Download document as text file
         const downloadDocument = () => {
           if (!generatedDocument.value) return;

           const blob = new Blob([generatedDocument.value], { type: 'text/plain' });
           const url = URL.createObjectURL(blob);
           const a = document.createElement('a');
           a.href = url;
           a.download = `${selectedTemplate.value}-document.txt`;
           document.body.appendChild(a);
           a.click();
           document.body.removeChild(a);
           URL.revokeObjectURL(url);
         };

         onMounted(() => {
           loadTemplates();
         });

         return {
           templates,
           selectedTemplate,
           templateContent,
           variables,
           generatedDocument,
           isGenerating,
           qualityAssessment,
           loadTemplate,
           generateDocument,
           downloadDocument
         };
       }
     };
     </script>
     ```

