   - Add caching for frequently used templates:
     ```python
     class CachedDocumentGenerator:
         def __init__(self, model_service, cache_size=100):
             self.model_service = model_service
             self.cache = {}
             self.cache_size = cache_size
             self.cache_hits = 0
             self.cache_misses = 0

         def generate_document(self, template, variables, max_length=2048):
             # Create a cache key from template and variables
             cache_key = self._create_cache_key(template, variables)

             # Check if result is in cache
             if cache_key in self.cache:
                 self.cache_hits += 1
                 return self.cache[cache_key]

             # Generate document
             self.cache_misses += 1
             result = self.model_service.generate_document(
                 template, variables, max_length
             )

             # Store in cache
             if len(self.cache) >= self.cache_size:
                 # Remove oldest entry
                 oldest_key = next(iter(self.cache))
                 del self.cache[oldest_key]

             self.cache[cache_key] = result
             return result

         def _create_cache_key(self, template, variables):
             # Create a deterministic cache key
             variables_str = json.dumps(variables, sort_keys=True)
             return f"{hash(template)}:{hash(variables_str)}"

         def get_cache_stats(self):
             total = self.cache_hits + self.cache_misses
             hit_rate = self.cache_hits / total if total > 0 else 0
             return {
                 "hits": self.cache_hits,
                 "misses": self.cache_misses,
                 "hit_rate": hit_rate,
                 "cache_size": len(self.cache),
                 "max_cache_size": self.cache_size
             }
     ```

