    // Add to database-helper.ts
    static async withRetry<T>(operation: () => Promise<T>, retries = 3, delay = 1000): Promise<T> {
      try {
        return await operation();
      } catch (err) {
        if (retries <= 0) throw err;

        console.log(`Operation failed, retrying in ${delay}ms. Retries left: ${retries}`);
        await new Promise(resolve => setTimeout(resolve, delay));
        return this.withRetry(operation, retries - 1, delay * 2);
      }
    }

    // Use in tests
    test('handles database connection issues gracefully', async ({ page }) => {
      // Simulate intermittent database connection
