    async function waitForDatabaseUpdate(condition: () => Promise<boolean>, timeout = 5000) {
      const startTime = Date.now();
      while (Date.now() - startTime < timeout) {
        if (await condition()) return true;
        await new Promise(r => setTimeout(r, 100));
