   ```typescript
   // src/services/ProcessService.ts
   import { ConvertProcess } from '../models/ConvertProcess';

   export class ProcessService {
     static async getAllProcesses() {
       return ConvertProcess.query().orderBy('processNumber');
     }

     static async getProcessByNumber(processNumber: number) {
       return ConvertProcess.query().findOne({ processNumber });
     }

     static async getNextProcess(currentProcessNumber: number) {
       return ConvertProcess.query()
         .where('processNumber', '>', currentProcessNumber)
         .orderBy('processNumber')
         .first();
     }

