     static async getAllProcesses(req: Request, res: Response) {
       try {
         const processes = await ProcessService.getAllProcesses();
         res.json(processes);
       } catch (error) {
         res.status(500).json({ error: 'Failed to fetch processes' });
       }
     }

     static async getProcessById(req: Request, res: Response) {
       try {
         const process = await ConvertProcess.query().findById(req.params.id);
         if (!process) {
