   # services/websocket_service.py
   from fastapi import WebSocket, WebSocketDisconnect
   import asyncio
   import json
   from typing import Dict, List, Set

   class TestStreamingService:
       def __init__(self):
           self.active_connections: Dict[str, Set[WebSocket]] = {}
           self.test_sessions: Dict[str, dict] = {}

       async def connect(self, websocket: WebSocket, test_session_id: str):
           await websocket.accept()
           if test_session_id not in self.active_connections:
               self.active_connections[test_session_id] = set()
           self.active_connections[test_session_id].add(websocket)

       async def disconnect(self, websocket: WebSocket, test_session_id: str):
           self.active_connections[test_session_id].discard(websocket)

       async def broadcast_test_event(self, test_session_id: str, event_data: dict):
           if test_session_id in self.active_connections:
               for connection in self.active_connections[test_session_id]:
                   await connection.send_text(json.dumps(event_data))
   ```

