   // services/navigationService.js
   export const NavigationService = {
     // Define application sections and their corresponding ports
     portMap: {
       mainApp: {
         port: 3000,
         sections: ['dashboard', 'company', 'projects', 'users', 'upload', 'system', 'help']
       },
       testApp: {
         port: 3015,
         sections: ['test-management', 'completed-tests']
       }
     },

     // Generate correct URL based on menu section
     generateUrl(section, path = '') {
       const baseUrl = window.location.protocol + '//' + window.location.hostname;

       // Determine correct port for the section
       let port;
       if (this.portMap.mainApp.sections.includes(section)) {
         port = this.portMap.mainApp.port;
       } else if (this.portMap.testApp.sections.includes(section)) {
         port = this.portMap.testApp.port;
       } else {
         console.error(`Unknown section: ${section}`);
         return '#';
       }

       return `${baseUrl}:${port}/${path}`;
     }
   };
