         try {
           loading.value = true;
           // Handle create or update
           if (actionItem.id) {
             // Update existing
             await actionItemsService.updateActionItem(actionItem.id, actionItem);
           } else {
             // Create new
             const projectId = parseInt(route.params.projectId);
             await actionItemsService.createActionItem({ ...actionItem, projectId });
           }
           await fetchActionItems();
           closeModal();
         } catch (err) {
           error.value = 'Det gick inte att spara åtgärdspunkten. Försök igen senare.';
           console.error(err);
         } finally {
           loading.value = false;
