           }
         }
       };

       const closeModal = () => {
         showModal.value = false;
         selectedActionItem.value = null;
       };

       const formatDate = (dateString) => {
         if (!dateString) return '';
         const date = new Date(dateString);
         return date.toLocaleDateString('sv-SE');
       };

