   ```javascript
   // services/portNavigationService.js
   export const PortNavigationService = {
     getMainAppUrl(path = '') {
       const baseUrl = import.meta.env.VITE_MAIN_APP_URL || 'http://localhost:3000';
       return `${baseUrl}${path.startsWith('/') ? path : `/${path}`}`;
     },

     getTestAppUrl(path = '') {
       const baseUrl = import.meta.env.VITE_TEST_APP_URL || 'http://localhost:3015';
       return `${baseUrl}${path.startsWith('/') ? path : `/${path}`}`;
     },

     getCurrentEnvironment() {
       return window.location.port === '3015' ? 'test' : 'main';
     },

     navigateToEnvironment(targetEnv, path, preserveContext = true) {
       const currentEnv = this.getCurrentEnvironment();
       if (currentEnv === targetEnv) return;

       const targetUrl = targetEnv === 'test' 
         ? this.getTestAppUrl(path)
         : this.getMainAppUrl(path);

       if (preserveContext) {
         // Store current state for potential retrieval
         localStorage.setItem('lastEnvironmentContext', JSON.stringify({
           sourceEnv: currentEnv,
           path: window.location.pathname,
           timestamp: Date.now()
         }));
       }

       window.location.href = targetUrl;
     }
   };
   ```

