   // services/crossWindowSync.js
   export const CrossWindowSync = {
     broadcastState(key, data) {
       localStorage.setItem(`sync_${key}`, JSON.stringify({
         data,
         timestamp: Date.now()
       }));

       // Trigger storage event in other tabs/windows
       window.dispatchEvent(new StorageEvent('storage', {
         key: `sync_${key}`,
         newValue: JSON.stringify({
           data,
           timestamp: Date.now()
         })
       }));
     },

     listenForStateChanges(key, callback) {
       const handler = (event) => {
         if (event.key === `sync_${key}` && event.newValue) {
           const { data, timestamp } = JSON.parse(event.newValue);
           callback(data, timestamp);
         }
       };

       window.addEventListener('storage', handler);
       return () => window.removeEventListener('storage', handler);
     }
   };
   ```

