This task involves updating the health check implementation in the frontend to use the new API endpoint structure:

1. Create a health check utility wrapper:
   ```typescript
   // src/services/health/healthCheckService.ts
   import { ApiService } from '@/services/api/apiService';

   export class HealthCheckService {
     private apiService: ApiService;
     private primaryEndpoint = '/api/v1/security/health';
     private legacyEndpoint = '/api/health';

     constructor(apiService: ApiService) {
       this.apiService = apiService;
     }

     /**
      * Attempts to check system health using the primary endpoint first,
      * falling back to the legacy endpoint if the primary fails
      */
     async checkHealth() {
       try {
         // Try primary endpoint first
         return await this.apiService.get(this.primaryEndpoint);
       } catch (error) {
         console.warn('Primary health endpoint failed, falling back to legacy endpoint', error);
         // Fall back to legacy endpoint
         return await this.apiService.get(this.legacyEndpoint);
       }
     }

     /**
      * Force check using only the primary endpoint
      */
     async checkHealthPrimary() {
       return await this.apiService.get(this.primaryEndpoint);
     }

     /**
      * Force check using only the legacy endpoint
      */
     async checkHealthLegacy() {
       return await this.apiService.get(this.legacyEndpoint);
     }
   }
   ```

