tasks.testStrategy:
1. Unit Testing:
   - Create unit tests for the HealthCheckService:
     ```typescript
     // tests/unit/services/health/healthCheckService.spec.ts
     import { describe, it, expect, vi, beforeEach } from 'vitest';
     import { HealthCheckService } from '@/services/health/healthCheckService';
     import { ApiService } from '@/services/api/apiService';

     describe('HealthCheckService', () => {
       let healthCheckService: HealthCheckService;
       let mockApiService: ApiService;

       beforeEach(() => {
         mockApiService = {
           get: vi.fn()
         } as unknown as ApiService;

         healthCheckService = new HealthCheckService(mockApiService);
       });

       it('should call primary endpoint first', async () => {
         mockApiService.get.mockResolvedValueOnce({ status: 'ok' });

         await healthCheckService.checkHealth();

         expect(mockApiService.get).toHaveBeenCalledWith('/api/v1/security/health');
         expect(mockApiService.get).not.toHaveBeenCalledWith('/api/health');
       });

       it('should fall back to legacy endpoint if primary fails', async () => {
         mockApiService.get.mockRejectedValueOnce(new Error('Primary failed'))
                        .mockResolvedValueOnce({ status: 'ok' });

         const result = await healthCheckService.checkHealth();

         expect(mockApiService.get).toHaveBeenCalledWith('/api/v1/security/health');
         expect(mockApiService.get).toHaveBeenCalledWith('/api/health');
         expect(result).toEqual({ status: 'ok' });
       });

       it('should throw error if both endpoints fail', async () => {
         mockApiService.get.mockRejectedValue(new Error('Endpoint failed'));

         await expect(healthCheckService.checkHealth()).rejects.toThrow('Endpoint failed');
       });
     });
     ```

